class Result(object):
    '''The result of a parse() or search().

    Fixed results may be looked up using result[index]. Named results may be
    looked up using result['name'].
    '''
    def __init__(self, fixed, named, spans):
        self.fixed = fixed
        self.named = named
        self.spans = spans

    def __getitem__(self, item):
        if isinstance(item, slice):
            # R10: Support slice access - return tuple of subset
            return self.fixed[item]
        if isinstance(item, int):
            return self.fixed[item]
        return self.named[item]

    def __contains__(self, value):
        # R2: Check if value exists in fixed or named results
        if value in self.fixed:
            return True
        # Check if value is in any of the named values (including nested dicts)
        return self._value_in_named(value, self.named)

    def _value_in_named(self, value, obj):
        """Recursively check if value exists in nested named dict."""
        if isinstance(obj, dict):
            for v in obj.values():
                if self._value_in_named(value, v):
                    return True
        elif isinstance(obj, tuple):
            if value in obj:
                return True
        else:
            if obj == value:
                return True
        return False

    def __repr__(self):
        return '<%s %r %r>' % (self.__class__.__name__, self.fixed,
            self.named)

